/// (node start, node count, value start, value count, dim) per codebook: 0 the scalefactor codebook, 1..=11 the spectral codebooks by number.
/// [spec r01 §6.1]
pub static HCB_AT: [[u32; 5]; 12] = [
    [0, 120, 0, 121, 1],
    [120, 80, 121, 324, 4],
    [200, 80, 445, 324, 4],
    [280, 80, 769, 324, 4],
    [360, 80, 1093, 324, 4],
    [440, 80, 1417, 162, 2],
    [520, 80, 1579, 162, 2],
    [600, 63, 1741, 128, 2],
    [663, 63, 1869, 128, 2],
    [726, 168, 1997, 338, 2],
    [894, 168, 2335, 338, 2],
    [1062, 288, 2673, 578, 2],
];
/// Codebook `book`: 0 the scalefactor codebook, 1..=11 spectral codebook `book`. [spec r01 §6.1]
pub fn codebook(book: usize) -> Codebook {
    let [n0, nn, v0, vn, dim] = HCB_AT[book];
    Codebook {
        nodes: &HCB_NODES[n0 as usize..(n0 + nn) as usize],
        dim: dim as u8,
        values: &HCB_VALUES[v0 as usize..(v0 + vn) as usize],
    }
}

/// Whether spectral codebook `cb` carries signs in its values (else sign bits follow). [spec r01 §6.1]
pub static HCB_SIGNED: [bool; 12] = [
    false, true, true, false, false, true, true, false, false, false, false, false,
];

